func TestSendCommand_CreatesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)
	store := csuite.NewStore(db)

	args := []string{"send", "--from", "kyle", "--to", "alex", "--subject", "Test", "--priority", "high", "--type", "request", "--body", "Hello"}
	err := run(args, db, io.Discard)
	if err != nil {
		t.Fatalf("run() failed: %v", err)
	}

	var msg csuite.CsuiteInboxMessage
	err = db.First(&msg).Error
	if err != nil {
		t.Fatalf("failed to find created message: %v", err)
	}

	if msg.FromAgent != "kyle" {
		t.Errorf("expected from kyle, got %s", msg.FromAgent)
	}
	if msg.ToAgent != "alex" {
		t.Errorf("expected to alex, got %s", msg.ToAgent)
	}
	if msg.Subject != "Test" {
		t.Errorf("expected subject Test, got %s", msg.Subject)
	}
	if msg.Priority != csuite.PriorityHigh {
		t.Errorf("expected priority high, got %s", msg.Priority)
	}
	if msg.Type != csuite.MessageTypeRequest {
		t.Errorf("expected type request, got %s", msg.Type)
	}
	if msg.Body != "Hello" {
		t.Errorf("expected body Hello, got %s", msg.Body)
	}
}

