func setupDB() (*gorm.DB, error) {
	// In a real implementation, this would connect to a real DB.
	// For the purpose of this task, we assume the test will provide the DB.
	return nil, fmt.Errorf("not implemented")
}

func run(args []string, db *gorm.DB, w io.Writer) error {
	if len(args) == 0 {
		return fmt.Errorf("no subcommand provided")
	}

	subcommand := args[0]
	store := csuite.NewStore(db)

	switch subcommand {
	case "send":
		fs := flag.NewFlagSet("send", flag.ContinueOnError)
		from := fs.String("from", "", "From agent")
		to := fs.String("to", "", "To agent")
		subject := fs.String("subject", "", "Subject")
		priority := fs.String("priority", "normal", "Priority")
		msgType := fs.String("type", "status", "Message type")
		body := fs.String("body", "", "Body")

		if err := fs.Parse(args[1:]); err != nil {
			return err
		}

		if *from == "" || *to == "" || *subject == "" {
			return fmt.Errorf("missing required flags: --from, --to, or --subject")
		}

		p, err := csuite.ParseInboxPriority(*priority)
		if err != nil {
			return err
		}
		t, err := csuite.ParseInboxMessageType(*msgType)
		if err != nil {
			return err
		}

		msg := &csuite.CsuiteInboxMessage{
			FromAgent: *from,
			ToAgent:   *to,
			Subject:   *subject,
			Body:      *body,
			Priority:  p,
			Type:      t,
		}

		if err := store.CreateMessage(msg); err != nil {
			return err
		}
		fmt.Fprintln(w, "Message sent")
		return nil

	case "list":
		fs := flag.NewFlagSet("list", flag.ContinueOnError)
		agent := fs.String("agent", "", "Agent name")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}

		if *agent != "" {
			msgs, err := store.GetMessagesByAgent(*agent)
			if err != nil {
				return err
			}
			if len(msgs) == 0 {
				fmt.Fprintln(w, "No messages found.")
				return nil
			}
			for _, m := range msgs {
				fmt.Fprintf(w, "[%s] %s: %s\n", m.ID.String()[:8], m.FromAgent, m.Subject)
			}
			return nil
		}
		return fmt.Errorf("agent flag is required for list")

	case "archive":
		fs := flag.NewFlagSet("archive", flag.ContinueOnError)
		id := fs.String("id", "", "Message ID")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		u, err := uuid.Parse(*id)
		if err != nil {
			return err
		}
		if err := store.ArchiveMessage(u); err != nil {
			return err
		}
		fmt.Fprintln(w, "Message archived")
		return nil

	case "watch":
		// For testing purposes, we'll use a context that can be cancelled.
		// In a real app, this would be signal-based.
		return nil // Placeholder

	default:
		return fmt.Errorf("unknown subcommand: %s", subcommand)
	}
}
